import 'package:freezed_annotation/freezed_annotation.dart';

part 'hint_ui.freezed.dart';

/// A hint, as a screen reader says it: the square it suggests, counting
/// [row] and [col] from 0 at the top left, and how many dice the move would
/// capture ([captures], 0 for none). The board shows it with marks.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class HintUi with _$HintUi {
  const factory HintUi({
    required int row,
    required int col,
    required int captures,
  }) = _HintUi;
}
